   707	internal static class CommentJson
   708	{
   709	    // Defensive client-side ceilings for the current comment API boundary.
   710	    // They keep malformed or compromised responses from producing unbounded
   711	    // agent context/stdout while allowing normal comment payload sizes. These
   712	    // are not a server contract; update the constants and tests together if
   713	    // the API publishes larger supported limits.
   714	    private const int MaxComments = 1000;
   715	    private const int MaxAuthorLength = 256;
   716	    private const int MaxTimestampLength = 128;
   717	    private const int MaxContentLength = 8192;
   718	
   719	    private static readonly string[] CreatedCommentIdPropertyNames = ["id", "commentId"];
   720	    private static readonly string[] CommentArrayPropertyNames = ["comments", "items", "data"];
   721	    private static readonly string[] TimestampPropertyNames = ["timestamp", "createdAt", "createdOn", "created", "updatedAt"];
   722	    private static readonly string[] ContentPropertyNames = ["content", "body", "text"];
   723	    private static readonly string[] NestedAuthorPropertyNames = ["displayName", "name", "email", "id"];
   724	    private static readonly string[] FallbackAuthorPropertyNames = ["authorName", "createdBy", "createdByName", "userName", "userId"];
   725	
   726	    // The service has returned these aliases across scaffold iterations. Keep
   727	    // accepted names centralized so the API boundary remains easy to audit.
   728	    public static string ExtractCreatedCommentId(string raw)
   729	    {
   730	        if (string.IsNullOrWhiteSpace(raw))
   731	        {
   732	            throw new InvalidOperationException("API response did not include a comment id.");
   733	        }
   734	
   735	        using var document = ParseDocument(raw);
   736	        var root = document.RootElement;
   737	        if (root.ValueKind == JsonValueKind.String)
   738	        {
   739	            var value = root.GetString();
   740	            if (!string.IsNullOrWhiteSpace(value))
   741	            {
   742	                return value;
   743	            }
   744	        }
   745	
   746	        if (FirstScalar(root, CreatedCommentIdPropertyNames) is { } id ||
   747	            TryGetNestedScalar(root, "comment", "id", out id))
   748	        {
   749	            if (!string.IsNullOrWhiteSpace(id))
   750	            {
   751	                return id;
   752	            }
   753	        }
   754	
   755	        throw new InvalidOperationException("API response did not include a comment id.");
   756	    }
   757	
   758	    public static IReadOnlyList<TaskComment> ReadComments(string raw)
   759	    {
   760	        if (string.IsNullOrWhiteSpace(raw))
   761	        {
   762	            throw new InvalidOperationException("API response was not a comment array or wrapper object.");
   763	        }
   764	
   765	        using var document = ParseDocument(raw);
   766	        var root = document.RootElement;
   767	        var comments = new List<TaskComment>();
   768	        foreach (var comment in EnumerateCommentElements(root))
   769	        {
   770	            if (comments.Count >= MaxComments)
   771	            {
   772	                throw new InvalidOperationException($"API returned more than {MaxComments} comments.");
   773	            }
   774	
   775	            comments.Add(ReadComment(comment, comments.Count));
   776	        }
   777	
   778	        return comments;
   779	    }
