   781	    private static TaskComment ReadComment(JsonElement comment, int index)
   782	    {
   783	        if (comment.ValueKind != JsonValueKind.Object)
   784	        {
   785	            throw new InvalidOperationException($"API comment at index {index} was not an object.");
   786	        }
   787	
   788	        return new TaskComment(
   789	            RequiredAuthor(comment, index),
   790	            RequiredScalar(comment, index, "timestamp", MaxTimestampLength, TimestampPropertyNames),
   791	            RequiredScalar(comment, index, "content", MaxContentLength, ContentPropertyNames));
   792	    }
   793	
   794	    private static JsonDocument ParseDocument(string raw)
   795	    {
   796	        try
   797	        {
   798	            return JsonDocument.Parse(raw);
   799	        }
   800	        catch (JsonException exception)
   801	        {
   802	            throw new InvalidOperationException("API response was malformed JSON.", exception);
   803	        }
   804	    }
   805	
   806	    private static IEnumerable<JsonElement> EnumerateCommentElements(JsonElement root)
   807	    {
   808	        if (root.ValueKind == JsonValueKind.Array)
   809	        {
   810	            foreach (var comment in root.EnumerateArray())
   811	            {
   812	                yield return comment;
   813	            }
   814	
   815	            yield break;
   816	        }
   817	
   818	        if (root.ValueKind == JsonValueKind.Object)
   819	        {
   820	            foreach (var propertyName in CommentArrayPropertyNames)
   821	            {
   822	                if (TryGetProperty(root, propertyName, out var property))
   823	                {
   824	                    if (property.ValueKind == JsonValueKind.Array)
   825	                    {
   826	                        foreach (var comment in property.EnumerateArray())
   827	                        {
   828	                            yield return comment;
   829	                        }
   830	
   831	                        yield break;
   832	                    }
   833	
   834	                    throw new InvalidOperationException(
   835	                        $"API response property '{propertyName}' was not a comment array.");
   836	                }
   837	            }
   838	
   839	            throw new InvalidOperationException(
   840	                "API response did not include a comments, items, or data comment array.");
   841	        }
   842	
   843	        throw new InvalidOperationException("API response was not a comment array or wrapper object.");
   844	    }
   845	
   846	    private static string RequiredAuthor(JsonElement comment, int index)
   847	    {
   848	        if (TryGetProperty(comment, "author", out var author))
   849	        {
   850	            if (TryConvertScalar(author, out var authorValue))
   851	            {
   852	                return BoundedScalar(authorValue, index, "author", MaxAuthorLength);
   853	            }
   854	
   855	            if (author.ValueKind == JsonValueKind.Object)
   856	            {
   857	                var nestedAuthor = FirstScalar(author, NestedAuthorPropertyNames);
   858	                if (nestedAuthor is not null)
   859	                {
   860	                    return BoundedScalar(nestedAuthor, index, "author", MaxAuthorLength);
   861	                }
   862	            }
   863	        }
   864	
   865	        var fallbackAuthor = FirstScalar(comment, FallbackAuthorPropertyNames);
   866	        if (fallbackAuthor is not null)
   867	        {
   868	            return BoundedScalar(fallbackAuthor, index, "author", MaxAuthorLength);
   869	        }
   870	
   871	        throw new InvalidOperationException($"API comment at index {index} did not include an author.");
   872	    }
   873	
   874	    private static string RequiredScalar(
   875	        JsonElement root,
   876	        int index,
   877	        string fieldName,
   878	        int maxLength,
   879	        params string[] propertyNames)
   880	    {
   881	        var value = FirstScalar(root, propertyNames);
   882	        if (value is not null)
   883	        {
   884	            return BoundedScalar(value, index, fieldName, maxLength);
   885	        }
   886	
   887	        throw new InvalidOperationException(
   888	            $"API comment at index {index} did not include a {fieldName}.");
   889	    }
   890	
   891	    private static string BoundedScalar(string value, int index, string fieldName, int maxLength)
   892	    {
   893	        if (value.Length <= maxLength)
   894	        {
   895	            return value;
   896	        }
   897	
   898	        throw new InvalidOperationException(
   899	            $"API comment at index {index} {fieldName} exceeded {maxLength} characters.");
   900	    }
