   902	    private static bool TryGetNestedScalar(JsonElement root, string propertyName, string nestedPropertyName, out string value)
   903	    {
   904	        value = "";
   905	        if (!TryGetProperty(root, propertyName, out var property) || property.ValueKind != JsonValueKind.Object)
   906	        {
   907	            return false;
   908	        }
   909	
   910	        return TryGetScalar(property, nestedPropertyName, out value);
   911	    }
   912	
   913	    private static string? FirstScalar(JsonElement root, params string[] propertyNames)
   914	    {
   915	        foreach (var propertyName in propertyNames)
   916	        {
   917	            if (TryGetScalar(root, propertyName, out var value))
   918	            {
   919	                return value;
   920	            }
   921	        }
   922	
   923	        return null;
   924	    }
   925	
   926	    private static bool TryGetScalar(JsonElement root, string propertyName, out string value)
   927	    {
   928	        value = "";
   929	        if (!TryGetProperty(root, propertyName, out var property))
   930	        {
   931	            return false;
   932	        }
   933	
   934	        return TryConvertScalar(property, out value);
   935	    }
   936	
   937	    private static bool TryGetProperty(JsonElement root, string propertyName, out JsonElement property)
   938	    {
   939	        property = default;
   940	        if (root.ValueKind != JsonValueKind.Object)
   941	        {
   942	            return false;
   943	        }
   944	
   945	        foreach (var candidate in root.EnumerateObject())
   946	        {
   947	            if (StringComparer.OrdinalIgnoreCase.Equals(candidate.Name, propertyName))
   948	            {
   949	                property = candidate.Value;
   950	                return true;
   951	            }
   952	        }
   953	
   954	        return false;
   955	    }
