  1002	internal static class UntrustedText
  1003	{
  1004	    // Bound API diagnostics to one small terminal page while preserving useful context.
  1005	    private const int MaxDiagnosticLength = 4096;
  1006	
  1007	    public static string SingleLine(string value)
  1008	    {
  1009	        return EscapeControls(value);
  1010	    }
  1011	
  1012	    public static string Diagnostic(string value)
  1013	    {
  1014	        var escaped = EscapeControls(value);
  1015	        if (escaped.Length <= MaxDiagnosticLength)
  1016	        {
  1017	            return escaped;
  1018	        }
  1019	
  1020	        return string.Concat(escaped.AsSpan(0, MaxDiagnosticLength), "... [truncated]");
  1021	    }
  1022	
  1023	    private static string EscapeControls(string value)
  1024	    {
  1025	        StringBuilder? builder = null;
  1026	        for (var index = 0; index < value.Length; index++)
  1027	        {
  1028	            var replacement = ControlReplacement(value[index]);
  1029	            if (replacement is null)
  1030	            {
  1031	                builder?.Append(value[index]);
  1032	                continue;
  1033	            }
  1034	
  1035	            if (builder is null)
  1036	            {
  1037	                builder = new StringBuilder(value.Length + replacement.Length);
  1038	                builder.Append(value.AsSpan(0, index));
  1039	            }
  1040	
  1041	            builder.Append(replacement);
  1042	        }
  1043	
  1044	        return builder?.ToString() ?? value;
  1045	    }
  1046	
  1047	    private static string? ControlReplacement(char value)
  1048	    {
  1049	        return value switch
  1050	        {
  1051	            '\b' => @"\b",
